<!--
  Vista administrativa AdminSettingsView. La ruta comprueba rol y permiso; la vista carga, presenta y modifica el recurso mediante su store.
  En <script> se declaran imports, estado y funciones; <template> describe la interfaz y <style> limita su presentación.
-->
<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { IconArchive, IconBuilding, IconMapPin, IconPhoto, IconPlus, IconShieldCheck } from '@tabler/icons-vue'
import AdminPageHeading from '../../components/admin/AdminPageHeading.vue'
import GymLocationPicker from '../../components/admin/GymLocationPicker.vue'
import AppAlert from '../../components/ui/AppAlert.vue'
import AppBadge from '../../components/ui/AppBadge.vue'
import AppButton from '../../components/ui/AppButton.vue'
import AppCard from '../../components/ui/AppCard.vue'
import AppDialog from '../../components/ui/AppDialog.vue'
import AppDrawer from '../../components/ui/AppDrawer.vue'
import AppInput from '../../components/ui/AppInput.vue'
import AppSelect from '../../components/ui/AppSelect.vue'
import AppTextarea from '../../components/ui/AppTextarea.vue'
import AppToast from '../../components/ui/AppToast.vue'
import { useAdminStore } from '../../stores/admin'
import { useAdminManagementStore } from '../../stores/adminManagement'
import { usePublicGymsStore } from '../../stores/publicGyms'

const props = defineProps({ create: Boolean })
const router = useRouter(); const admin = useAdminStore(); const management = useAdminManagementStore(); const publicGyms = usePublicGymsStore()
const editing = ref(Boolean(props.create)); const locationOpen = ref(false); const archiveOpen = ref(false); const archiveReason = ref(''); const saving = ref(false); const error = ref(''); const fields = ref({}); const selectedFile = ref(null); const fileInput = ref(null)
const toast = reactive({ open: false, title: '', message: '', tone: 'success' })
const gym = reactive({ nombre: '', nombre_legal: '', descripcion: '', direccion: '', ciudad: '', departamento: '', pais: 'Uruguay', latitud: '', longitud: '', zona_horaria: 'America/Montevideo', telefono: '', email: '', horarios: '', categorias: '', servicios: '', estado: 'borrador', verificacion_estado: 'pendiente' })
const location = reactive({ id: null, nombre: '', direccion: '', ciudad: '', departamento: '', pais: 'Uruguay', latitud: '', longitud: '', zona_horaria: 'America/Montevideo', telefono: '', email: '', horarios: '', estado: 'activa', es_principal: false })
const canVerify = computed(() => admin.globalRole === 'admin_general')
const statusTone = computed(() => management.gym?.estado === 'publicado' ? 'success' : management.gym?.estado === 'temporalmente_cerrado' ? 'warning' : 'neutral')
function join(value) { if (Array.isArray(value)) return value.join(', '); if (value && typeof value === 'object') return Object.entries(value).map(([key, item]) => `${key.replaceAll('_', ' ')}: ${item}`).join(', '); return '' }
function split(value) { return String(value || '').split(',').map((item) => item.trim()).filter(Boolean) }
function payload(source) { return { ...source, horarios: split(source.horarios), categorias: split(source.categorias), servicios: split(source.servicios) } }
function applyGym(data) { if (!data) return; Object.assign(gym, { ...data, horarios: join(data.horarios), categorias: join(data.categorias), servicios: join(data.servicios) }) }
function notify(title, message = '', tone = 'success') { Object.assign(toast, { open: true, title, message, tone }) }
async function load() { if (props.create) return; const data = await management.loadGym(admin.activeGymId); if (data) applyGym(data); await management.loadLocations(admin.activeGymId) }
async function saveGym() { saving.value = true; error.value = ''; fields.value = {}; const result = props.create ? await management.createGym(payload(gym)) : await management.saveGym(admin.activeGymId, payload(gym)); saving.value = false; if (!result.ok) { error.value = result.message; fields.value = result.fields; return } await publicGyms.refreshAndFocus(result.data); if (props.create) { await admin.loadContext(); if (result.data.estado === 'publicado') { await router.replace({ name: 'gyms', query: { gimnasio: result.data.slug, estado: 'creado' } }); return } if (!admin.isGlobalAdmin) await admin.selectGym(result.data.id); await router.replace({ name: admin.isGlobalAdmin ? 'admin-summary' : 'admin-settings' }); return } applyGym(result.data); editing.value = false; await admin.loadContext(); notify(result.data.estado === 'publicado' ? 'Configuración guardada y mapa actualizado' : 'Configuración guardada', result.data.estado === 'publicado' ? 'La ficha pública ya utiliza esta ubicación.' : 'El gimnasio no se muestra públicamente mientras esté inactivo o en borrador.') }
function openLocation(item = null) { Object.assign(location, item ? { ...item, horarios: join(item.horarios) } : { id: null, nombre: '', direccion: '', ciudad: '', departamento: '', pais: gym.pais || 'Uruguay', latitud: gym.latitud, longitud: gym.longitud, zona_horaria: gym.zona_horaria, telefono: '', email: '', horarios: '', estado: 'activa', es_principal: false }); error.value = ''; fields.value = {}; locationOpen.value = true }
async function saveLocation() { saving.value = true; const result = await management.saveLocation(admin.activeGymId, { ...location, horarios: split(location.horarios) }, location.id); saving.value = false; if (!result.ok) { error.value = result.message; fields.value = result.fields; return } if (location.es_principal) { const updated = await management.loadGym(admin.activeGymId); if (updated) { applyGym(updated); await publicGyms.refreshAndFocus(updated) } } locationOpen.value = false; notify(location.id ? 'Sede actualizada' : 'Sede creada', location.es_principal ? 'La ubicación pública y el mapa quedaron sincronizados.' : '') }
async function upload() { if (!selectedFile.value) return; saving.value = true; const result = await management.upload(selectedFile.value, 'gimnasio_imagen'); saving.value = false; if (!result.ok) { notify('No se pudo subir la imagen', result.message, 'danger'); return } selectedFile.value = null; await load(); notify('Imagen actualizada') }
async function archiveGym() { saving.value = true; error.value = ''; const archivedId = admin.activeGymId; const result = await management.archiveGym(archivedId, archiveReason.value); saving.value = false; if (!result.ok) { error.value = result.message; return } publicGyms.remove(archivedId); await publicGyms.load(true); archiveOpen.value = false; await admin.loadContext(); await router.replace({ name: 'admin-summary' }) }
watch(() => admin.version, load)
onMounted(load)
</script>

<template>
  <section>
    <AdminPageHeading :title="create ? 'Nuevo gimnasio' : 'Configuración del gimnasio'" :description="create ? 'Registrá la identidad, validá la ubicación y elegí cuándo publicarlo.' : 'Datos comerciales, publicación, sedes e imagen del gimnasio activo.'"><template #actions><template v-if="!create && !editing"><AppButton variant="secondary" @click="router.push({ name: 'admin-gym-create' })"><template #icon><IconPlus :size="18" /></template>Nuevo gimnasio</AppButton><AppButton @click="editing = true">Editar información</AppButton></template></template></AdminPageHeading>

    <form v-if="editing" class="gym-form" @submit.prevent="saveGym"><AppAlert v-if="error" tone="danger" title="No pudimos guardar"><p>{{ error }}</p></AppAlert><section aria-labelledby="identity-title"><div class="section-title"><IconBuilding :size="21" /><div><h2 id="identity-title">Identidad y contacto</h2><p>Información visible y legal del gimnasio.</p></div></div><div class="form-grid"><AppInput v-model="gym.nombre" label="Nombre comercial" name="gym-name" required :error="fields.nombre" /><AppInput v-model="gym.nombre_legal" label="Nombre legal" name="gym-legal-name" required :error="fields.nombre_legal" /><AppTextarea v-model="gym.descripcion" class="span-2" label="Descripción" name="gym-description" :rows="4" required :error="fields.descripcion" /><AppInput v-model="gym.telefono" label="Teléfono" name="gym-phone" :error="fields.telefono" /><AppInput v-model="gym.email" label="Correo" name="gym-email" type="email" :error="fields.email" /></div></section><section aria-labelledby="location-title"><div class="section-title"><IconMapPin :size="21" /><div><h2 id="location-title">Sede principal</h2><p>La dirección y el marcador son la única ubicación pública utilizada por la lista y el mapa.</p></div></div><div class="form-grid"><AppInput v-model="gym.direccion" class="span-2" label="Dirección completa" name="gym-address" required :error="fields.direccion" /><AppInput v-model="gym.ciudad" label="Ciudad o localidad" name="gym-city" required :error="fields.ciudad" /><AppInput v-model="gym.departamento" label="Departamento" name="gym-department" required :error="fields.departamento" /><AppInput v-model="gym.pais" class="span-2" label="País" name="gym-country" required :error="fields.pais" /><GymLocationPicker :direccion="gym.direccion" :ciudad="gym.ciudad" :pais="gym.pais" :latitud="gym.latitud" :longitud="gym.longitud" @update:latitud="gym.latitud = $event" @update:longitud="gym.longitud = $event" /><AppInput v-model="gym.latitud" label="Latitud" name="gym-latitude" inputmode="decimal" required :error="fields.latitud" hint="También podés ingresarla manualmente." /><AppInput v-model="gym.longitud" label="Longitud" name="gym-longitude" inputmode="decimal" required :error="fields.longitud" hint="También podés ingresarla manualmente." /><AppInput v-model="gym.zona_horaria" class="span-2" label="Zona horaria IANA" name="gym-timezone" required :error="fields.zona_horaria" /></div></section><section aria-labelledby="operation-title"><div class="section-title"><IconShieldCheck :size="21" /><div><h2 id="operation-title">Operación y publicación</h2><p>Sólo los gimnasios activos, verificados y con ubicación válida aparecen públicamente.</p></div></div><div class="form-grid"><AppInput v-model="gym.horarios" class="span-2" label="Horarios" name="gym-hours" hint="Ejemplo: Lunes a viernes 06:00–22:00, Sábado 08:00–18:00" /><AppInput v-model="gym.categorias" label="Categorías" name="gym-categories" /><AppInput v-model="gym.servicios" label="Servicios" name="gym-services" /><AppSelect v-model="gym.estado" label="Estado" name="gym-state" :options="[{ value: 'publicado', label: 'Activo' }, { value: 'inactivo', label: 'Inactivo' }, { value: 'borrador', label: 'Borrador' }, { value: 'temporalmente_cerrado', label: 'Cerrado temporalmente' }]" /><AppSelect v-if="canVerify" v-model="gym.verificacion_estado" label="Verificación" name="gym-verification" :options="[{ value: 'pendiente', label: 'Pendiente' }, { value: 'verificado', label: 'Verificado' }, { value: 'rechazado', label: 'Rechazado' }]" /></div></section><footer class="form-actions"><AppButton v-if="!create" type="button" variant="secondary" @click="editing = false; applyGym(management.gym)">Cancelar</AppButton><AppButton type="submit" :loading="saving">{{ create ? 'Crear gimnasio' : 'Guardar cambios' }}</AppButton></footer></form>

    <template v-else>
      <div class="gym-overview"><div><IconBuilding :size="24" /><span><strong>{{ management.gym?.nombre }}</strong><small>{{ management.gym?.nombre_legal }}</small></span></div><dl><div><dt>Estado</dt><dd><AppBadge :tone="statusTone">{{ management.gym?.estado === 'publicado' ? 'activo' : management.gym?.estado?.replaceAll('_', ' ') }}</AppBadge></dd></div><div><dt>Verificación</dt><dd>{{ management.gym?.verificacion_estado }}</dd></div><div><dt>Ubicación</dt><dd>{{ management.gym?.ciudad }}, {{ management.gym?.pais }}</dd></div><div><dt>Zona horaria</dt><dd>{{ management.gym?.zona_horaria }}</dd></div></dl></div>
      <section class="settings-section" aria-labelledby="locations-heading"><div class="section-heading"><div><h2 id="locations-heading">Sedes</h2><p>La sede principal sincroniza la ubicación pública del gimnasio.</p></div><AppButton variant="secondary" @click="openLocation()"><template #icon><IconPlus :size="17" /></template>Nueva sede</AppButton></div><div class="location-list"><button v-for="item in management.locations" :key="item.id" type="button" @click="openLocation(item)"><IconMapPin :size="19" /><span><strong>{{ item.nombre }}</strong><small>{{ item.direccion }} · {{ item.ciudad }}</small></span><AppBadge :tone="item.estado === 'activa' ? 'success' : 'neutral'">{{ item.es_principal ? 'Principal' : item.estado }}</AppBadge></button></div></section>
      <section class="settings-section" aria-labelledby="image-heading"><div class="section-heading"><div><h2 id="image-heading">Imagen pública</h2><p>JPG, PNG o WebP, hasta 5 MB. Se valida tipo real y dimensiones.</p></div></div><div class="upload-row"><IconPhoto :size="22" /><input ref="fileInput" class="visually-hidden" aria-label="Seleccionar imagen del gimnasio" type="file" accept="image/jpeg,image/png,image/webp" @change="selectedFile = $event.target.files?.[0] || null" /><AppButton variant="secondary" @click="fileInput?.click()">Seleccionar imagen</AppButton><span class="upload-name">{{ selectedFile?.name || 'Ningún archivo seleccionado' }}</span><AppButton :disabled="!selectedFile" :loading="saving" @click="upload">Subir imagen</AppButton></div></section>
      <section class="settings-section permissions-section"><h2>Permisos efectivos</h2><div><AppBadge v-for="permission in admin.permissions" :key="permission">{{ permission }}</AppBadge></div></section>
      <section v-if="['dueño', 'admin_general'].includes(admin.effectiveRole)" class="settings-section archive-section"><div><h2>Archivar gimnasio</h2><p>Oculta el gimnasio y sus sedes sin borrar el historial. No está permitido mientras existan membresías activas.</p></div><AppButton variant="secondary" @click="archiveReason = ''; error = ''; archiveOpen = true"><template #icon><IconArchive :size="17" /></template>Archivar gimnasio</AppButton></section>
    </template>

    <AppDrawer :open="locationOpen" :title="location.id ? 'Editar sede' : 'Nueva sede'" @close="locationOpen = false"><form id="location-form" class="drawer-form" @submit.prevent="saveLocation"><AppAlert v-if="error" tone="danger" title="No pudimos guardar la sede"><p>{{ error }}</p></AppAlert><AppInput v-model="location.nombre" label="Nombre" name="location-name" required :error="fields.nombre" /><AppInput v-model="location.direccion" label="Dirección completa" name="location-address" required :error="fields.direccion" /><AppInput v-model="location.ciudad" label="Ciudad o localidad" name="location-city" required :error="fields.ciudad" /><AppInput v-model="location.departamento" label="Departamento" name="location-department" required :error="fields.departamento" /><AppInput v-model="location.pais" label="País" name="location-country" required :error="fields.pais" /><GymLocationPicker :direccion="location.direccion" :ciudad="location.ciudad" :pais="location.pais" :latitud="location.latitud" :longitud="location.longitud" @update:latitud="location.latitud = $event" @update:longitud="location.longitud = $event" /><div class="drawer-grid"><AppInput v-model="location.latitud" label="Latitud" name="location-latitude" required :error="fields.latitud" /><AppInput v-model="location.longitud" label="Longitud" name="location-longitude" required :error="fields.longitud" /></div><AppInput v-model="location.zona_horaria" label="Zona horaria" name="location-timezone" required :error="fields.zona_horaria" /><AppInput v-model="location.telefono" label="Teléfono" name="location-phone" /><AppInput v-model="location.email" label="Correo" name="location-email" type="email" /><AppInput v-model="location.horarios" label="Horarios" name="location-hours" hint="Separados por comas." /><AppSelect v-model="location.estado" label="Estado" name="location-status" :options="[{ value: 'activa', label: 'Activa' }, { value: 'inactiva', label: 'Inactiva' }]" /></form><template #footer><div class="drawer-actions"><AppButton type="button" variant="secondary" @click="locationOpen = false">Cancelar</AppButton><AppButton type="submit" form="location-form" :loading="saving">Guardar sede</AppButton></div></template></AppDrawer>
    <AppDialog :open="archiveOpen" title="Archivar gimnasio" description="Esta acción lo quitará de la navegación y del catálogo público, pero conservará su historial." @close="archiveOpen = false"><div class="archive-dialog"><AppAlert v-if="error" tone="danger" title="No se puede archivar"><p>{{ error }}</p></AppAlert><AppTextarea v-model="archiveReason" label="Motivo" name="archive-reason" :rows="3" hint="Escribí al menos 8 caracteres. Quedará registrado en auditoría." /></div><template #footer><AppButton variant="secondary" @click="archiveOpen = false">Cancelar</AppButton><AppButton variant="danger" :disabled="archiveReason.trim().length < 8" :loading="saving" @click="archiveGym">Confirmar archivo</AppButton></template></AppDialog>
    <AppToast v-bind="toast" @close="toast.open = false" />
  </section>
</template>

<style scoped>
.gym-form { display: grid; gap: var(--space-10); margin-top: var(--space-6); }.gym-form > section { display: grid; gap: var(--space-5); border-top: 1px solid var(--border-subtle); padding-top: var(--space-7, 1.75rem); }.section-title { display: grid; grid-template-columns: 1.5rem 1fr; gap: var(--space-3); }.section-title svg { color: var(--info); }.section-title h2,.section-heading h2,.settings-section h2 { margin: 0 0 var(--space-2); font-size: 1.18rem; }.section-title p,.section-heading p { margin: 0; color: var(--text-secondary); font-size: .8rem; }.form-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: var(--space-4); }.span-2 { grid-column: 1 / -1; }.form-actions { display: flex; justify-content: flex-end; gap: var(--space-3); border-top: 1px solid var(--border-subtle); padding-top: var(--space-5); }.gym-overview { display: grid; grid-template-columns: minmax(16rem,.75fr) 1.25fr; gap: var(--space-8); margin-top: var(--space-6); border-top: 1px solid var(--border-subtle); border-bottom: 1px solid var(--border-subtle); padding: var(--space-6) 0; }.gym-overview > div { display: grid; grid-template-columns: 2rem 1fr; gap: var(--space-3); }.gym-overview > div svg { color: var(--info); }.gym-overview span { display: grid; gap: var(--space-1); }.gym-overview strong { font-size: 1.05rem; }.gym-overview small { color: var(--text-tertiary); }.gym-overview dl { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: var(--space-4); margin: 0; }.gym-overview dl div { display: grid; gap: var(--space-1); }.gym-overview dt { color: var(--text-tertiary); font-size: .7rem; }.gym-overview dd { margin: 0; color: var(--text-secondary); font-size: .8rem; }.settings-section { margin-top: var(--space-10); padding-top: var(--space-8); border-top: 1px solid var(--border-subtle); }.section-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--space-5); margin-bottom: var(--space-5); }.location-list { display: grid; border-top: 1px solid var(--border-subtle); }.location-list button { display: grid; min-height: 4.5rem; grid-template-columns: 1.5rem 1fr auto; align-items: center; gap: var(--space-3); border: 0; border-bottom: 1px solid var(--border-subtle); padding: var(--space-3) 0; background: transparent; color: var(--text-primary); cursor: pointer; text-align: left; }.location-list button:hover { background: var(--surface-1); }.location-list svg { color: var(--text-tertiary); }.location-list span { display: grid; gap: var(--space-1); }.location-list strong { font-size: .82rem; }.location-list small { color: var(--text-tertiary); font-size: .72rem; }.upload-row { display: grid; grid-template-columns: 1.5rem auto minmax(0,1fr) auto; align-items: center; gap: var(--space-4); border: 1px solid var(--border-subtle); border-radius: var(--radius-card); padding: var(--space-4); background: var(--surface-1); }.upload-row svg { color: var(--info); }.upload-name { overflow: hidden; color: var(--text-tertiary); font-size: .78rem; text-overflow: ellipsis; white-space: nowrap; }.permissions-section > div { display: flex; flex-wrap: wrap; gap: var(--space-2); }.archive-section { display: flex; align-items: center; justify-content: space-between; gap: var(--space-8); }.archive-section p { max-width: 48rem; margin: 0; color: var(--text-secondary); font-size: .8rem; }.archive-dialog { display: grid; gap: var(--space-5); }.drawer-form { display: grid; gap: var(--space-5); }.drawer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3); }.drawer-actions { display: flex; justify-content: flex-end; gap: var(--space-3); }
@media (max-width: 47.99rem) { .form-grid,.gym-overview { grid-template-columns: 1fr; }.span-2 { grid-column: auto; }.gym-overview dl { grid-template-columns: 1fr 1fr; }.section-heading,.archive-section { align-items: flex-start; flex-direction: column; }.upload-row { grid-template-columns: 1fr; }.location-list button { grid-template-columns: 1.5rem 1fr; }.location-list :deep(.app-badge) { grid-column: 2; justify-self: start; } }
@media (max-width: 24rem) { .gym-overview dl,.drawer-grid { grid-template-columns: 1fr; } }
</style>
